using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Setup: a source-gen context that only knows about "Person" ---
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1️⃣  Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣  Probe without throwing — TryGetTypeInfo returns false when
//     metadata isn't registered (here, Order is unknown to our context)
if (options.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo))
{
    Console.WriteLine($"Order metadata found: {orderInfo!.Type.Name}");
}
else
{
    Console.WriteLine("Order metadata NOT available — no exception thrown.");
}

// Also confirm the happy-path probe works
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probeInfo))
{
    Console.WriteLine($"Probe for Person succeeded: {probeInfo!.Type.Name}");
}

// --- Types -----------------------------------------------------------
record Person(string Name, int Age);
record Order(int Id, decimal Total);

[JsonSerializable(typeof(Person))]          // only Person is registered
partial class AppJsonContext : JsonSerializerContext;

